type TemporalQuery = Readonly<{
  view: TemporalView;
  request_time: string;
  world_at?: string;
  known_at: string;
  transition?: TemporalTransition;
}>;

type TemporalTransition = Readonly<{
  from: string;
  to: string;
}>;

